#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Section ParallelogramADEF. Variable R : realType. Let P := 'rV[R]_2. Variables A B C D E F : P. Hypothesis distinct_A_B : A != B. Hypothesis distinct_A_C : A != C. Hypothesis distinct_B_C : B != C. Hypothesis eq_AB_AC : dist A B = 28 /\ dist A C = 28. Hypothesis eq_BC : dist B C = 20. Hypothesis D_on_AB : exists tD : R, 0 < tD < 1 /\ D = (1 - tD) *: A + tD *: B. Hypothesis E_on_BC : exists tE : R, 0 < tE < 1 /\ E = (1 - tE) *: B + tE *: C. Hypothesis F_on_AC : exists tF : R, 0 < tF < 1 /\ F = (1 - tF) *: A + tF *: C. Hypothesis DE_parallel_AC : exists k1 : R, (E - D) = k1 *: (C - A). Theorem parallelogram_area_consistent : exists area : R, area > 0. Proof. Admitted. End
